script:
const accounts = [
    { name: "1110 - Наличные - AM", id: "kassa1-balance" }, 
    { name: "1111 - Клик - AM", id: "kassa2-balance" }, 
    { name: "1112 - Перечисление - AM", id: "kassa3-balance" }       
];

accounts.forEach(acc => {
    frappe.call({
        method: "erpnext.accounts.utils.get_balance_on",
        args: {
            account: acc.name
        },
        callback: function(r) {
            if (r && r.message !== undefined) {
                let formatted_balance = format_currency(r.message, frappe.boot.sysdefaults.currency);
                let el = root_element.querySelector(`#${acc.id}`);
                if (el) {
                    el.innerText = formatted_balance;
                }
            } else {
                let el = root_element.querySelector(`#${acc.id}`);
                if (el) {
                    el.innerText = "Xatolik";
                }
            }
        }
    });
});
